function MyComponent() {
  const [count, setCount] = useState(0);

  // RENDER PHASE: This runs every render
  console.log('Render phase - computing JSX');
  const expensiveValue = count * 2; // Pure computation

  useEffect(() => {
    // COMMIT PHASE: This runs after DOM is updated
    console.log('Commit phase - DOM is updated now');
  });

  // RENDER PHASE: Returning JSX
  return <div>{expensiveValue}</div>;
}

function List() {
  const [items, setItems] = useState(['A', 'B', 'C']);

  const shuffle = () => {
    setItems([...items].sort(() => Math.random() - 0.5));
  };

  return (
    <div>
      {items.map(item => (
        // WITH key: React tracks which item is which
        <div key={item}>{item}</div>

        // WITHOUT key: React updates all items every shuffle
        // <div>{item}</div>
      ))}
      <button onClick={shuffle}>Shuffle</button>
    </div>
  );
}

function Counter() {
  const [count, setCount] = useState(0);

  const handleClick = () => {
    // ❌ WRONG - reads stale count three times
    setCount(count + 1); // count is 0, sets to 1
    setCount(count + 1); // count is STILL 0, sets to 1
    setCount(count + 1); // count is STILL 0, sets to 1
    // Result: count becomes 1, not 3
  };

  const handleClickCorrect = () => {
    // ✅ CORRECT - updater function gets latest value
    setCount(c => c + 1); // c is 0, returns 1
    setCount(c => c + 1); // c is 1, returns 2
    setCount(c => c + 1); // c is 2, returns 3
    // Result: count becomes 3
  };

  return <div>{count}</div>;
}

// Without optimization - Child re-renders even when props don't change
function Parent() {
  const [count, setCount] = useState(0);
  const [other, setOther] = useState(0);

  return (
    <>
      <button onClick={() => setOther(other + 1)}>Change Other</button>
      <Child count={count} /> {/* Re-renders even when count unchanged */}
    </>
  );
}

// With React.memo - Child only re-renders when count changes
const Child = React.memo(function Child({ count }) {
  console.log('Child rendered');
  return <div>{count}</div>;
});

// Now clicking 'Change Other' doesn't re-render Child!
